//! The "scaffolded, not implemented" error channel for `com-amazonaws-lightsail-lightsail-20161128`.
//!
//! @generated by the emulator core scaffold op-stub generator.
//!
//! Every generated operation stub returns [`Scaffolded::not_implemented`], which the
//! framework renders as a protocol-correct **HTTP 501 `NotImplemented`**. Do not change
//! a stub to return a success value: a client, and any check that only asserts the call
//! succeeded, cannot tell an empty success from a real implementation. Implement the
//! operation, or leave the 501.
//!
//! ## The error type
//!
//! A stub's error type is `Scaffolded<{Op}ErrorModeled>` — the model's own error enum
//! plus the `NotImplemented` variant. Do not try to add `NotImplemented` to the
//! `#[operation_error]` enum directly; it accepts only variants the model declares.
//!
//! ## Implementing an operation
//!
//! Replace the `Err(..)` in the handler body with real behaviour. Each stub emits a
//! CONCRETE `impl From<{Op}ErrorModeled> for {Op}Error` beside its
//! alias, so `?` works through the wrapper and a modeled failure needs no ceremony:
//!
//! ```ignore
//! return Err(GetThingErrorModeled::ResourceNotFound(
//!     ResourceNotFound { message: Some("no such thing".into()) },
//! )
//! .into());
//! ```
//!
//! That impl is emitted per operation, not once for all of them — keep it that way if
//! you edit a stub.
//!
//! ## Once the operation is implemented
//!
//! Keep the `#[operation_error]` enum, the alias and the `From` impl.
//!
//! An implemented operation stops needing the 501, but the wrapper is also the only
//! place it can return an error its own model does not declare — `validation` above,
//! for a service whose model carries no client-input error. Delete the wrapper and the
//! handler has no way to refuse a bad request at all.
//!
//! ## This service's not-found envelope
//!
//! It is also where an error whose WIRE rendering differs from its modelled traits
//! lives. Lightsail answers a request naming a resource it cannot find with HTTP 400,
//! even though the model declares `@httpError(404)` on `NotFoundException`; a Lightsail
//! SDK client maps the failure from the body, not the status. The generated error enum
//! takes its status straight from the model's trait, so that envelope is
//! [`Scaffolded::NotFound`].
//!
//! What the body's `code` carries is the DISCRIMINATOR the refusing operation reports,
//! and Lightsail does not report one discriminator for the whole service: the resource
//! operations report the sub-classification [`DOES_NOT_EXIST_CODE`], while the alarm
//! operations report the modelled exception's own name
//! ([`NOT_FOUND_EXCEPTION_CODE`]) — including `PutAlarm`, whose not-found is about the
//! INSTANCE or database it was asked to watch, so it is the operation that decides the
//! discriminator and not the kind of resource it could not find. So a not-found path is
//! built through [`Scaffolded::resource_does_not_exist`] /
//! [`Scaffolded::does_not_exist`] for the resource operations and through
//! [`Scaffolded::alarm_resource_not_found`] /
//! [`Scaffolded::alarm_resource_not_found_within`] for the alarm operations.
//!
//! The WORDING is a per-operation choice too, and there are two of them:
//!
//! * an operation handed both the identifier and the kind of resource it addresses —
//!   every resource reader, updater and deleter, whose input member names one kind and
//!   one only — words the refusal with [`resource_does_not_exist_message`], "The
//!   &lt;ResourceType&gt; does not exist: &lt;name&gt;";
//! * an operation that had to SEARCH for an identifier among resource types words it
//!   with [`resource_not_found_within_types_message`], which names the types it looked
//!   among — `PutAlarm`'s monitored resource — and so do the alarm operations that
//!   address an alarm (`DeleteAlarm`, `TestAlarm`), whose recorded refusals carry that
//!   sentence with the single-entry list.
//!
//! An input-validation refusal carries its own discriminator, [`INVALID_PARAMS_CODE`],
//! which [`invalid_input`] puts in `code` — so every refusal this crate builds through
//! that one owner carries it.

use aws_smithy_schema::serde::{SerdeError, SerializableStruct, ShapeSerializer};
use aws_smithy_schema::{Schema, ShapeId, ShapeType};
use smithy_server_runtime::OperationError;

/// The `message` member of the synthetic `NotImplemented` error shape.
///
/// `with_xml_name("Message")` matches the casing the restXml / awsQuery error
/// envelopes use, so the same value renders correctly on the XML protocols and as
/// lowercase `message` on the JSON/CBOR ones.
static NOT_IMPLEMENTED_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#NotImplemented$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for the synthetic `NotImplemented` error shape.
///
/// Deliberately in the `smithy.framework` namespace: this shape is NOT in any
/// service's model, so it must not collide with a modeled shape. The wire `__type` /
/// `<Code>` comes from [`OperationError::shape_name`] below, not from this schema.
pub static NOT_IMPLEMENTED_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#NotImplemented",
        "smithy.framework",
        "NotImplemented",
    ),
    ShapeType::Structure,
    &[&NOT_IMPLEMENTED_MESSAGE],
);

/// The payload of a `NotImplemented` failure: which operation was called, and the
/// fact that it is scaffolded rather than broken.
#[derive(Debug, Clone)]
pub struct NotImplemented {
    pub message: String,
}

impl NotImplemented {
    /// A `NotImplemented` naming `operation`.
    ///
    /// The wording matters: it must read as "not written yet", never as "the emulator
    /// is broken", because that distinction is what a human triaging a failing fixture
    /// needs first.
    pub fn new(operation: &str) -> Self {
        Self {
            message: format!(
                "operation {operation} is scaffolded but not implemented in this emulator"
            ),
        }
    }
}

impl std::fmt::Display for NotImplemented {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "NotImplemented: {}", self.message)
    }
}

impl std::error::Error for NotImplemented {}

impl SerializableStruct for NotImplemented {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&NOT_IMPLEMENTED_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// The `message` member of the synthetic `ValidationException` error shape.
static VALIDATION_EXCEPTION_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#ValidationException$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for the synthetic `ValidationException` error shape.
///
/// In the `smithy.framework` namespace for the same reason as `NotImplemented`: the
/// shape is not in any service's model, so it must not collide with a modeled one.
/// If THIS service's model declares its own `ValidationException`, prefer that —
/// see [`Scaffolded::validation`].
pub static VALIDATION_EXCEPTION_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#ValidationException",
        "smithy.framework",
        "ValidationException",
    ),
    ShapeType::Structure,
    &[&VALIDATION_EXCEPTION_MESSAGE],
);

/// The payload of a `ValidationException`: why the request was refused.
#[derive(Debug, Clone)]
pub struct ValidationException {
    pub message: String,
}

impl ValidationException {
    /// A `ValidationException` carrying `message`.
    ///
    /// Say what was wrong with the request and name the member, the way the
    /// boundary validator does — the caller has to fix the request from this text
    /// alone.
    pub fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
        }
    }
}

impl std::fmt::Display for ValidationException {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "ValidationException: {}", self.message)
    }
}

impl std::error::Error for ValidationException {}

impl SerializableStruct for ValidationException {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&VALIDATION_EXCEPTION_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// The value the RESOURCE operations put in the `code` member of a rejection whose
/// cause is that the resource — or the catalog entry — the request names does not
/// exist.
///
/// A Lightsail SDK client branches on THIS, not on the HTTP status: the body's `code`
/// is what tells "already gone" apart from a transport failure.
pub const DOES_NOT_EXIST_CODE: &str = "DoesNotExist";

/// The value the ALARM operations put in the `code` member of the same rejection: the
/// modelled exception's own name.
///
/// `PutAlarm` reports it for the resource it was asked to watch and `DeleteAlarm` and
/// `TestAlarm` for the alarm itself, so what the discriminator depends on is the
/// operation that refuses the request rather than the kind of resource it looked for.
pub const NOT_FOUND_EXCEPTION_CODE: &str = "NotFoundException";

/// The value Lightsail puts in the `code` member of a refusal whose cause is that the
/// input does not conform to a validation rule of an input field — the
/// sub-classification that tells an input-validation refusal apart from the other 400s
/// an operation can answer, `OperationFailureException` among them.
///
/// It is what [`invalid_input`] puts in `code`, and every handler of this crate builds
/// its input refusal through that one owner, so a refusal cannot be served without the
/// discriminator a client branches on.
pub const INVALID_PARAMS_CODE: &str = "InvalidParams";

/// The modelled `InvalidInputException` this crate refuses a request with: `message`,
/// and the discriminator Lightsail reports for an input-validation refusal
/// ([`INVALID_PARAMS_CODE`]) in `code`.
///
/// The ONE owner of that pair. The shape's own `Default` is derived from the model, so
/// it carries no `code` — the member is a plain optional string there — and a body
/// without it hands an SDK client, which branches on `code` rather than on the HTTP
/// status, nothing to branch on. So every handler builds its refusal here rather than
/// from the shape's defaults, which is also what keeps the discriminator in one place
/// when the model is re-rendered.
pub fn invalid_input(message: impl Into<String>) -> crate::ops::types::InvalidInputException {
    crate::ops::types::InvalidInputException {
        code: Some(INVALID_PARAMS_CODE.to_string()),
        message: Some(message.into()),
        ..Default::default()
    }
}

/// The message Lightsail refuses a request that named a resource by BOTH its own
/// identifier and its kind with: fixed text naming the resource type, then the
/// identifier the request carried.
///
/// The fixed text is AWS's — "The ", " does not exist: " — and the variable parts are
/// the modelled `ResourceType` the refusing operation addresses (one of the
/// `crate::state::RESOURCE_TYPE_*` constants) and the identifier copied verbatim from
/// the request.
pub fn resource_does_not_exist_message(resource_type: &str, name: &str) -> String {
    format!("The {resource_type} does not exist: {name}")
}

/// The message Lightsail refuses a request whose identifier it had to SEARCH for among
/// resource types with: the service's fixed text around the identifier the request
/// carried and the bracketed list of the types that were searched.
///
/// Not the wording of a resource-addressed lookup — that one is
/// [`resource_does_not_exist_message`]. This one belongs to a refusal that had to
/// resolve an identifier whose kind the request did not state, and to the alarm
/// operations, whose recorded refusals word it this way even for a single-entry list.
/// The fixed text is AWS's, and the variable parts are the request's own identifier and
/// that type list.
pub fn resource_not_found_within_types_message(resource_types: &[&str], name: &str) -> String {
    format!(
        "The specified resource {name} does not exist within types [{}]. Please provide a \
         valid resource name.",
        resource_types.join(", ")
    )
}

/// The HTTP status Lightsail answers its `NotFoundException` with ON THE WIRE.
///
/// The model declares `@httpError(404)` on the shape, but the recorded Lightsail
/// endpoint answers **400** for a resource it cannot find, with the shape name in
/// `__type` and the refusing operation's discriminator in the body's `code`. The
/// recorded wire status governs, so this status — not the modelled one — is what
/// [`Scaffolded::NotFound`] renders.
pub const NOT_FOUND_WIRE_STATUS: u16 = 400;

/// An operation's error channel: either the synthetic scaffold signal, or one of the
/// operation's own modeled errors.
#[derive(Debug)]
pub enum Scaffolded<E> {
    /// The operation is generated but has no implementation. Renders as HTTP 501.
    NotImplemented(NotImplemented),
    /// A modeled error the operation declares. Renders with the model's own status.
    Modeled(E),
    /// The modelled `NotFoundException`, rendered at the status Lightsail answers it
    /// with on the wire ([`NOT_FOUND_WIRE_STATUS`]) rather than the `@httpError(404)`
    /// the model declares.
    ///
    /// It is a variant of its own, and not [`Modeled`](Self::Modeled), because the
    /// generated error enum reads its status straight off the model's trait and so can
    /// only answer 404. The BODY is the modelled shape and its schema, so the wire
    /// `__type` and every member (`code`, `message`, `docs`, `tip`) are exactly the
    /// model's.
    NotFound(crate::ops::types::NotFoundException),
    /// The request was refused as invalid. Renders as HTTP 400 with the error code
    /// `ValidationException`.
    ///
    /// On the JSON and CBOR protocols that is the same status and code the boundary
    /// validator answers with. Two differences are worth knowing, and neither is
    /// specific to this variant — every handler-returned error shares them:
    /// the awsJson families omit the `x-amzn-errortype` header that the boundary
    /// path sets, and the query protocols render a boundary refusal as
    /// `MalformedQueryString` rather than `ValidationException`, so a client
    /// matching on the error code there sees two codes for one logical failure.
    ValidationException(ValidationException),
}

impl<E> Scaffolded<E> {
    /// The scaffold signal for `operation`.
    pub fn not_implemented(operation: &str) -> Self {
        Self::NotImplemented(NotImplemented::new(operation))
    }

    /// Lightsail's rejection of a request that names a resource this account does not
    /// hold: HTTP 400, wire error `NotFoundException`, body `code` `DoesNotExist`, and
    /// a message built from the request — the identifier the request carried and the
    /// types the operation looks for it among.
    ///
    /// `resource_type` is a value of the modelled `ResourceType` enum, i.e. one of the
    /// `crate::state::RESOURCE_TYPE_*` constants, so the message names the resource the
    /// way every other Lightsail response does. The request named that kind itself — the
    /// input member it carried the identifier in admits one kind and one only — so the
    /// message is the resource-addressed wording
    /// [`resource_does_not_exist_message`]. An operation that addresses a resource
    /// WITHOUT being told which kind it is names every kind it looked among, through
    /// [`Scaffolded::resource_does_not_exist_within`].
    pub fn resource_does_not_exist(resource_type: &str, name: &str) -> Self {
        Self::does_not_exist(resource_does_not_exist_message(resource_type, name))
    }

    /// The same rejection for an operation that had to look for `name` among SEVERAL
    /// resource types, which the message then lists in the order the operation
    /// resolves them in.
    ///
    /// The wording is [`resource_not_found_within_types_message`], and it is the one a
    /// SEARCH answers with: the kind of the resource is not something the request
    /// stated, so the refusal reports what was searched instead of naming one type.
    pub fn resource_does_not_exist_within(resource_types: &[&str], name: &str) -> Self {
        Self::does_not_exist(resource_not_found_within_types_message(resource_types, name))
    }

    /// The not-found rejection of an ALARM operation: the same HTTP 400, the same wire
    /// error `NotFoundException` and the searched-types message
    /// ([`resource_not_found_within_types_message`]) their recorded refusals carry, with
    /// the discriminator those operations report in `code` —
    /// [`NOT_FOUND_EXCEPTION_CODE`] rather than [`DOES_NOT_EXIST_CODE`].
    pub fn alarm_resource_not_found(resource_type: &str, name: &str) -> Self {
        Self::alarm_resource_not_found_within(&[resource_type], name)
    }

    /// [`Self::alarm_resource_not_found`] for an alarm operation that looks for `name`
    /// among SEVERAL resource types, which the message then lists in the order the
    /// operation resolves them in.
    pub fn alarm_resource_not_found_within(resource_types: &[&str], name: &str) -> Self {
        Self::NotFound(crate::ops::types::NotFoundException {
            code: Some(NOT_FOUND_EXCEPTION_CODE.to_string()),
            message: Some(resource_not_found_within_types_message(resource_types, name)),
            ..Default::default()
        })
    }

    /// The same `DoesNotExist` envelope for a rejection whose message is not the
    /// resource-type/name one — a request naming an entry of a PUBLISHED catalog (a
    /// blueprint, say) rather than a resource of the account.
    pub fn does_not_exist(message: impl Into<String>) -> Self {
        Self::NotFound(crate::ops::types::NotFoundException {
            code: Some(DOES_NOT_EXIST_CODE.to_string()),
            message: Some(message.into()),
            ..Default::default()
        })
    }

    /// Refuse the request as invalid, with HTTP 400 `ValidationException`.
    ///
    /// Reach for this when the request is wrong in a way the model cannot express,
    /// so the boundary validator passed it: a value outside a rule the service
    /// enforces but does not model, or a combination of members that cannot hold
    /// together. Answer it INSTEAD of `not_implemented` — a 501 says "nobody has
    /// written this yet", which is a different claim and is counted as one.
    ///
    /// If this service's model declares its own `ValidationException` (or another
    /// client-input error) use THAT: the modeled shape may carry members beyond
    /// `message` — a `reason`, a field list — and a real client reads them. When the
    /// operation already lists it, it is a plain variant on the generated error enum;
    /// `#[operation_error]`'s `extra_errors` is only for widening in a shape the
    /// SERVICE models that this OPERATION does not list.
    pub fn validation(message: impl Into<String>) -> Self {
        Self::ValidationException(ValidationException::new(message))
    }
}

impl<E: std::fmt::Display> std::fmt::Display for Scaffolded<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented(e) => write!(f, "{e}"),
            Self::Modeled(e) => write!(f, "{e}"),
            Self::NotFound(e) => write!(f, "{e}"),
            Self::ValidationException(e) => write!(f, "{e}"),
        }
    }
}

/// `source()` forwards to the modeled error rather than taking the default `None`, so a
/// modeled error's own `source()` is preserved through the wrapper.
impl<E: std::error::Error + 'static> std::error::Error for Scaffolded<E> {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::NotImplemented(e) => e.source(),
            Self::Modeled(e) => e.source(),
            Self::NotFound(e) => e.source(),
            Self::ValidationException(e) => e.source(),
        }
    }
}

/// Every `OperationError` method delegates to the modeled error, so wrapping an
/// implemented operation's error channel changes NOTHING about how that error is
/// rendered. Only the synthetic variant behaves differently — and it is the one that
/// must answer 501.
impl<E: OperationError> OperationError for Scaffolded<E> {
    fn as_serializable(&self) -> &dyn SerializableStruct {
        match self {
            Self::NotImplemented(e) => e,
            Self::Modeled(e) => e.as_serializable(),
            Self::NotFound(e) => e,
            Self::ValidationException(e) => e,
        }
    }

    fn variant_schema(&self) -> &'static Schema {
        match self {
            Self::NotImplemented(_) => &NOT_IMPLEMENTED_SCHEMA,
            Self::Modeled(e) => e.variant_schema(),
            // The MODELLED shape's own schema: the body is the model's, only the
            // status differs from the model's trait.
            Self::NotFound(_) => &crate::ops::types::SCHEMA_NOT_FOUND_EXCEPTION,
            Self::ValidationException(_) => &VALIDATION_EXCEPTION_SCHEMA,
        }
    }

    /// The wire error code (`__type` on JSON/CBOR, `<Code>` on XML).
    ///
    /// Keep the literal as it is: changing it changes the wire error code clients match
    /// on. It is intentionally not tied to the Rust variant name.
    fn shape_name(&self) -> &'static str {
        match self {
            Self::NotImplemented(_) => "NotImplemented",
            Self::Modeled(e) => e.shape_name(),
            Self::NotFound(_) => crate::ops::types::NotFoundException::shape_name(),
            Self::ValidationException(_) => "ValidationException",
        }
    }

    /// 501 for the scaffold signal.
    ///
    /// Keep it 501 and not a 5xx server fault: SDK retry classifiers treat those as
    /// retryable, so a client would retry an operation that can never succeed.
    fn http_status(&self) -> u16 {
        match self {
            Self::NotImplemented(_) => 501,
            Self::Modeled(e) => e.http_status(),
            Self::NotFound(_) => NOT_FOUND_WIRE_STATUS,
            Self::ValidationException(_) => 400,
        }
    }

    fn query_error_code(&self) -> Option<&'static str> {
        match self {
            // No awsQuery code: the synthetic shape is not in the model, so there is
            // no `awsQueryError` trait to honour. The 501 + `<Code>NotImplemented`
            // envelope carries the signal on the query protocols too.
            Self::NotImplemented(_) => None,
            Self::Modeled(e) => e.query_error_code(),
            // The modelled `NotFoundException` carries no `awsQueryError` trait, and
            // this service's protocol is awsJson1_1 either way.
            Self::NotFound(_) => None,
            // Same reason: the synthetic shape carries no `awsQueryError` trait.
            Self::ValidationException(_) => None,
        }
    }
}
